const response = $input.first().json;

// Get AI Agent output
const content = response.output;

if (!content) {
  throw new Error("No output received from AI Agent");
}

let parsed;

try {

  // Remove markdown code blocks if present
  const cleanContent = content
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  parsed = JSON.parse(cleanContent);

} catch (error) {

  // Fallback feedback if AI returns invalid JSON
  const webhookData = $("Webhook - AI Feedback").first().json.body;

  parsed = {
    overall_performance:
      `Great effort! You scored ${webhookData.percentage}% on the ${webhookData.difficulty || "quiz"} quiz about ${webhookData.topic || "this topic"}.`,

    strengths:
      "You completed the quiz and demonstrated understanding of several concepts.",

    areas_to_improve:
      "Review the questions you answered incorrectly and revisit the related concepts.",

    practical_suggestion:
      "Practice another quiz on the same topic and focus on understanding explanations for incorrect answers."
  };

}

return [
  {
    json: parsed
  }
];

const room = $input.first().json;
const b = $('JoinRoom - Prepare').first().json;

if (!room || !room.id) {
  throw new Error('Room not found');
}

if (room.status !== 'waiting') {
  throw new Error('Contest already started');
}

const maxPlayers = Number(room.max_players);

if (!Number.isInteger(maxPlayers) || maxPlayers < 2) {
  throw new Error('Invalid max_players configuration');
}

return [{
  json: {
    room_id: room.id,
    room_code: room.room_code,
    user_id: b.user_id,
    player_name: b.player_name,
    max_players: maxPlayers
  }
}];

const b = $json.body || $json;

const room_code = b.room_code;
const room_id = b.room_id;

if (!room_code && !room_id) {
  throw new Error('Missing room_code or room_id');
}

return [{
  json: {
    room_code: room_code || null,
    room_id: room_id || null
  }
}];

const room=$('GetRoom - Get Room').first().json;
const players=$input.all().map(i=>({user_id:i.json.user_id,player_name:i.json.player_name,is_host:i.json.is_host,joined_at:i.json.joined_at}));
return [{json:{status:'success',action:'getRoom',room,players,player_count:players.length}}];

const room=$input.first().json; const b=$('StartContest - Prepare').first().json;
if(room.host_id!==b.host_id) throw new Error('Only the host can start the contest');
if(!room.quiz_id && !b.quiz_id) throw new Error('Missing quiz_id. Generate quiz first.');
return [{json:{id:room.id,status:'started',quiz_id:b.quiz_id||room.quiz_id}}];

const room=$('GetContest - Room').first().json;
if(room.status!=='started') throw new Error('Contest has not started');
const questions=$input.all().map((i,index)=>({id:i.json.id,order:index+1,question:i.json.question,option_a:i.json.option_a,option_b:i.json.option_b,option_c:i.json.option_c,option_d:i.json.option_d}));
return [{json:{status:'success',action:'getContest',room_id:room.id,quiz:{id:room.quiz_id,topic:room.topic,difficulty:room.difficulty},questions}}];

const b=$json.body||{};
for(const k of ['room_id','user_id','player_name','answers','completion_time_seconds']) if(b[k]===undefined||b[k]===null) throw new Error(`Missing ${k}`);
return [{json:{...b}}];

const room_id = $('Leaderboard - Prepare').first().json.room_id;

const results = $input.all()
  .map(i => i.json)
  .sort((a, b) =>
    Number(b.score) - Number(a.score) ||
    Number(a.completion_time_seconds) - Number(b.completion_time_seconds)
  )
  .map((r, i) => ({
    rank: i + 1,
    player_name: r.player_name,
    user_id: r.user_id,
    score: r.score,
    total_questions: r.total_questions,
    percentage: r.percentage,
    completion_time_seconds: r.completion_time_seconds,
    submitted_at: r.submitted_at
  }));

return [{
  json: {
    status: 'success',
    action: 'getLeaderboard',
    room_id,
    leaderboard: results
  }
}];

const room = $('SubmitResult - Get Room').first().json;
const b = $('SubmitResult - Prepare').first().json;
const qs = $input.all().map(i => i.json);

if (room.status !== 'started') {
  throw new Error('Contest is not active');
}

if (!Array.isArray(b.answers) && typeof b.answers !== 'object') {
  throw new Error('answers must be an object or array');
}

const answers = b.answers || {};

let score = 0;

for (const q of qs) {
  const questionId = String(q.id);

  let givenAnswer;

  if (Array.isArray(answers)) {
    const answerObj = answers.find(
      a => String(a.question_id) === questionId
    );

    givenAnswer = answerObj?.answer;
  } else {
    givenAnswer =
      answers[questionId] ??
      answers[q.id];
  }

  if (
    givenAnswer !== undefined &&
    String(givenAnswer).trim() === String(q.correct_answer).trim()
  ) {
    score++;
  }
}

const total_questions = qs.length;

const percentage =
  total_questions > 0
    ? Number(((score / total_questions) * 100).toFixed(2))
    : 0;

const completion_time_seconds =
  Number(b.completion_time_seconds);

if (
  !Number.isFinite(completion_time_seconds) ||
  completion_time_seconds < 0
) {
  throw new Error('Invalid completion_time_seconds');
}

return [{
  json: {
    room_id: b.room_id,
    user_id: b.user_id,
    player_name: b.player_name,
    score,
    total_questions,
    percentage,
    completion_time_seconds
  }
}];

const quiz = JSON.parse($input.first().json.text);

// Get original request data from Webhook
const webhookData = $('Webhook1').first().json.body;

// Return one item per question
return quiz.map(question => ({
  json: {
    ...question,

    topic: webhookData.topic,
    difficulty: webhookData.difficulty,
    number_of_questions: webhookData.number_of_questions
  }
}));

const b = $json.body || {};

const required = [
  'host_id',
  'player_name',
  'topic',
  'difficulty',
  'number_of_questions',
  'max_players'
];

for (const k of required) {
  if (b[k] === undefined || b[k] === null || b[k] === '') {
    throw new Error(`Missing ${k}`);
  }
}

const numQuestions = Number(b.number_of_questions);
const maxPlayers = Number(b.max_players);

if (!Number.isInteger(numQuestions) || numQuestions < 1) {
  throw new Error('number_of_questions must be a positive integer');
}

if (!Number.isInteger(maxPlayers) || maxPlayers < 2 || maxPlayers > 10) {
  throw new Error('max_players must be between 2 and 10');
}

const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

let room_code = '';

for (let i = 0; i < 8; i++) {
  room_code += chars[Math.floor(Math.random() * chars.length)];
}

return [
  {
    json: {
      host_id: b.host_id,
      player_name: b.player_name,
      topic: b.topic,
      difficulty: b.difficulty,
      num_questions: numQuestions,
      max_players: maxPlayers,
      quiz_id: null,
      room_code,
      status: 'waiting'
    }
  }
];

const raw = $input.first().json.text;

if (!raw) {
  throw new Error('AI did not return question data');
}

let questions;

try {
  questions = JSON.parse(raw);
} catch (error) {
  throw new Error('AI returned invalid JSON');
}

if (!Array.isArray(questions)) {
  throw new Error('AI response must be an array of questions');
}

if (questions.length === 0) {
  throw new Error('No questions were generated');
}

const quiz = $('Create Quiz2').first().json;
const requested = $('CreateRoom - Prepare1').first().json.num_questions;

if (questions.length < requested) {
  throw new Error(`AI generated ${questions.length} questions but ${requested} were requested`);
}

return questions.slice(0, requested).map((q, index) => ({
  json: {
    quiz_id: quiz.id,
    question: q.question,
    option_a: q.option_a,
    option_b: q.option_b,
    option_c: q.option_c,
    option_d: q.option_d,
    correct_answer: q.correct_answer,
    explanation: q.explanation,
    question_number: index + 1
  }
}));

const room = $input.first().json;
const original = $('CreateRoom - Prepare1').first().json;

return [
  {
    json: {
      ...room,
      user_id: original.host_id,
      player_name: original.player_name,
      is_host: true
    }
  }
];

const room = $('CreateRoom - Prepare Host1').first().json;

return [
  {
    json: {
      status: 'success',
      action: 'createRoom',
      room: {
        id: room.id,
        room_code: room.room_code,
        host_id: room.host_id,
        quiz_id: room.quiz_id,
        topic: room.topic,
        difficulty: room.difficulty,
        num_questions: room.num_questions,
        max_players: room.max_players,
        status: room.status
      },
      players: [
        {
          user_id: room.user_id,
          player_name: room.player_name,
          is_host: true
        }
      ]
    }
  }
];

const items = $input.all();

return [{
  json: {
    questions_inserted: items.length,
    completed: true
  }
}];

const players = $input.all();

const room = $('JoinRoom - Check Room').first().json;
const request = $('JoinRoom - Prepare').first().json;

const maxPlayers = Number(room.max_players);

if (players.some(item => item.json.user_id === request.user_id)) {
  throw new Error('User has already joined this room');
}

if (players.length >= maxPlayers) {
  throw new Error('Room is full');
}

return [{
  json: {
    room_id: room.id,
    user_id: request.user_id,
    player_name: request.player_name,
    is_host: false
  }
}];

const quiz = $("Get a row").first().json;

const questions = $("Get many rows").all().map(item => ({
    question: item.json.question,
    option_a: item.json.option_a,
    option_b: item.json.option_b,
    option_c: item.json.option_c,
    option_d: item.json.option_d,
    correct_answer: item.json.correct_answer,
    explanation: item.json.explanation
}));

return [
    {
        json: {
            quiz: {
                id: quiz.id,
                topic: quiz.topic,
                difficulty: quiz.difficulty,
                number_of_questions: quiz.number_of_questions
            },
            questions: questions
        }
    }
];
